def extract(folder):
    for path, text in FILES.items():
        dest = os.path.join(folder, *path.split("/"))
        os.makedirs(os.path.dirname(dest) or ".", exist_ok=True)
        with open(dest, "w", encoding="utf-8", newline="\n") as f:
            f.write(text)
    print(f"Wrote {len(FILES)} files to {os.path.abspath(folder)}")
    print("Open index.html through a web server (e.g. 'python -m http.server' inside that folder), or upload the folder to GitHub Pages / Netlify.")


class Handler(http.server.BaseHTTPRequestHandler):
    def do_GET(self, head_only=False):
        path = self.path.split("?", 1)[0].split("#", 1)[0].lstrip("/") or "index.html"
        if path.endswith("/"):
            path += "index.html"
        text = FILES.get(path)  # only files in the bundle can be served — no disk access
        if text is None:
            self.send_error(404, "Not found")
            return
        body = text.encode("utf-8")
        ext = os.path.splitext(path)[1]
        self.send_response(200)
        self.send_header("Content-Type", TYPES.get(ext, "application/octet-stream"))
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-cache")
        for k, v in SECURITY_HEADERS.items():
            self.send_header(k, v)
        self.end_headers()
        if not head_only:
            self.wfile.write(body)

    def do_HEAD(self):
        self.do_GET(head_only=True)

    def log_message(self, fmt, *args):
        pass


def local_ip():
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("8.8.8.8", 80))
        ip = s.getsockname()[0]
        s.close()
        return ip
    except OSError:
        return "127.0.0.1"


def serve(port, lan, open_browser):
    host = "0.0.0.0" if lan else "127.0.0.1"
    server = http.server.ThreadingHTTPServer((host, port), Handler)
    url = f"http://localhost:{port}/"
    print("Hallelujoy is running!")
    print(f"  On this computer:  {url}")
    if lan:
        print(f"  On your Wi-Fi:     http://{local_ip()}:{port}/   (phones & laptops on the same network)")
    print("Press Ctrl+C to stop.")
    if open_browser:
        threading.Timer(0.8, lambda: webbrowser.open(url)).start()
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nStopped. God bless!")


def main():
    ap = argparse.ArgumentParser(description="Hallelujoy — Bible & gospel party games")
    ap.add_argument("--port", type=int, default=8000, help="port to serve on (default 8000)")
    ap.add_argument("--lan", action="store_true", help="allow other devices on your network to connect")
    ap.add_argument("--no-browser", action="store_true", help="don't open a browser tab")
    ap.add_argument("--extract", metavar="FOLDER", help="write the website files to FOLDER instead of serving")
    a = ap.parse_args()
    if a.extract:
        extract(a.extract)
    else:
        serve(a.port, a.lan, not a.no_browser)


if __name__ == "__main__":
    main()
